/* Offline replay ABI: context lifetime, certificates, transcript and trace. */
#include "switch_ctx.h"

#include <stdlib.h>
#include <string.h>

#include "offline_api.h"

void collector_ingress(epic_ctx_t *ctx, int rank, const uint8_t *frame,
                       size_t length);

static void *xalloc(size_t n) { return calloc(n ? n : 1, 1); }

void *epic_open(int primitive, int mode, int root, uint32_t count, uint32_t words,
                uint32_t capacity, uint32_t start, uint32_t trace_limit) {
    epic_ctx_t *ctx = xalloc(sizeof(*ctx));
    if (!ctx) {
        return NULL;
    }
    ctx->kind = primitive;
    ctx->mode = mode;
    ctx->root = root;
    ctx->K = count;
    ctx->D = words;
    ctx->N = capacity;
    ctx->start = start & 0x00ffffffu;
    ctx->m = count / 4;
    ctx->req_mask = (primitive == (int)EPIC_PRIM_BCAST)
                        ? (uint8_t)(1u << (unsigned)root)
                        : (uint8_t)0xfu;
    size_t stride;
    if (primitive == (int)EPIC_PRIM_ALLGATHER) {
        stride = 16 * (size_t)words;
    } else if (primitive == (int)EPIC_PRIM_BARRIER) {
        stride = 0;
    } else {
        stride = 4 * (size_t)words;
    }
    ctx->stride = stride;
    ctx->used = xalloc(capacity);
    ctx->slot_p = xalloc(capacity * sizeof(*ctx->slot_p));
    ctx->slot_mask = xalloc(capacity);
    ctx->pool = xalloc((size_t)capacity * (stride ? stride : 1));
    init_outc_decl(ctx);
    if (!ctx->used || !ctx->slot_p || !ctx->slot_mask || !ctx->pool) {
        epic_close(ctx);
        return NULL;
    }
    ctx->budget = -1; /* unlimited until a budget event says otherwise */
    epic_sha256_init(&ctx->sha);
    if (trace_limit > EPIC_TRACE_MAX) {
        trace_limit = EPIC_TRACE_MAX;
    }
    if (trace_limit) {
        ctx->trace = xalloc((size_t)trace_limit * sizeof(*ctx->trace));
        if (!ctx->trace) {
            epic_close(ctx);
            return NULL;
        }
        ctx->trace_limit = trace_limit;
    }
    return ctx;
}

void epic_close(void *context) {
    epic_ctx_t *ctx = context;
    if (!ctx) {
        return;
    }
    free(ctx->used);
    free(ctx->slot_p);
    free(ctx->slot_mask);
    free(ctx->pool);
    free(ctx->trace);
    free(ctx);
}

int epic_ingress(void *context, int rank, const uint8_t *frame, size_t length) {
    collector_ingress(context, rank, frame, length);
    return 0;
}

int epic_flush(void *context) {
    service(context, -1);
    return 0;
}

int epic_retry(void *context, int rank) {
    service(context, rank);
    return 0;
}

void epic_budget(void *context, int64_t remaining) { ctx->budget = remaining; }

void epic_state(void *context, uint64_t *state) {
    epic_ctx_t *ctx = context;
    memset(state, 0, 32 * sizeof(*state));
    state[0] = ctx->retired;
    state[1] = ctx->occupied;
    for (int r = 0; r < EPIC_STAR4_HOSTS; r++) {
        state[2 + r] = ctx->R[r];
        state[6 + r] = ctx->sent[r];
        state[10 + r] = ctx->down[r];
        state[14 + r] = ctx->up[r];
    }
    state[18] = ctx->c_data;
    state[19] = ctx->c_ack;
    state[20] = ctx->c_tx_data;
    state[21] = ctx->c_tx_ack;
    state[22] = ctx->c_accept;
    state[23] = ctx->c_dup;
    state[24] = ctx->c_block;
    state[25] = ctx->c_stale;
    state[26] = ctx->c_wire;
    state[27] = ctx->c_endpoint;
    state[28] = ctx->c_ignore;
    state[29] = ctx->c_fail;
    state[30] = ctx->c_overwrite;
    state[31] = 0;
}

static uint64_t fold_byte(uint64_t hash, uint8_t value) {
    return (hash ^ value) * UINT64_C(1099511628211);
}

static uint64_t fold_bytes(uint64_t hash, const uint8_t *data, size_t len) {
    for (size_t i = 0; i < len; i++) {
        hash = fold_byte(hash, data[i]);
    }
    return hash;
}

uint64_t epic_digest(void *context) {
    epic_ctx_t *ctx = context;
    uint64_t h = UINT64_C(14695981039346656037);
    uint32_t window = ctx->retired + ctx->N;
    if (window > ctx->K) {
        window = ctx->K;
    }
    size_t paybytes = 4 * (size_t)ctx->D;
    for (uint32_t p = ctx->retired; p < window; p++) {
        uint32_t i;
        if (!slot_index(ctx, p, &i)) {
            continue;
        }
        uint8_t mask = ctx->slot_mask[i];
        uint64_t wide = p;
        uint8_t key[8];
        for (int j = 0; j < 8; j++) {
            key[j] = (uint8_t)(wide >> (8 * j));
        }
        h = fold_bytes(h, key, 8);
        h = fold_byte(h, mask);
        h = fold_byte(h, mask == ctx->req_mask ? 1 : 0);
        const uint8_t *base = slot_base(ctx, i);
        if (ctx->kind == (int)EPIC_PRIM_ALLGATHER) {
            for (int r = 0; r < EPIC_STAR4_HOSTS; r++) {
                int present = (mask >> r) & 1;
                h = fold_byte(h, (uint8_t)present);
                if (present) {
                    h = fold_bytes(h, base + (size_t)r * paybytes, paybytes);
                }
            }
        } else if (ctx->kind == (int)EPIC_PRIM_BCAST) {
            h = fold_bytes(h, base, paybytes);
        } else if (ctx->kind == (int)EPIC_PRIM_BARRIER) {
            /* barrier retains no payload bytes */
        } else {
            const uint32_t *agg = (const uint32_t *)base;
            for (uint32_t j = 0; j < ctx->D; j++) {
                uint8_t le[4];
                uint32_t v = agg[j];
                le[0] = (uint8_t)v;
                le[1] = (uint8_t)(v >> 8);
                le[2] = (uint8_t)(v >> 16);
                le[3] = (uint8_t)(v >> 24);
                h = fold_bytes(h, le, 4);
            }
        }
    }
    return h;
}

uint64_t epic_packets(void *context) { return ((epic_ctx_t *)context)->packets; }
uint64_t epic_bytes(void *context) { return ((epic_ctx_t *)context)->bytes; }

size_t epic_trace_count(void *context) {
    return ((epic_ctx_t *)context)->trace_n;
}

size_t epic_trace_item(void *context, size_t index, int *rank, uint8_t *buf,
                       size_t cap) {
    epic_ctx_t *ctx = context;
    if (index >= ctx->trace_n || cap < ctx->trace[index].len) {
        return 0;
    }
    *rank = ctx->trace[index].rank;
    memcpy(buf, ctx->trace[index].frame, ctx->trace[index].len);
    return ctx->trace[index].len;
}

void epic_transcript_sha(void *context, char *hex65) {
    static const char digits[] = "0123456789abcdef";
    uint8_t out[32];
    epic_sha256_final(&((epic_ctx_t *)context)->sha, out);
    for (int i = 0; i < 32; i++) {
        hex65[i * 2] = digits[out[i] >> 4];
        hex65[i * 2 + 1] = digits[out[i] & 15];
    }
    hex65[64] = '\0';
}
